// The account tools stay mounted in their own popups. Keeping their DOM in
// place preserves subscriptions, lazy disclosure loading, and in-progress forms.
import { lock, unlock } from './scroll-lock.js';

let mounted = null;

export function closePanelPopup(name, options) {
  return mounted?.close(name, options) ?? false;
}

// Components can supply a popup after their lazy module has upgraded.
export function openPanelPopup(name, trigger, panel) {
  if (!mounted && typeof document !== 'undefined' && document.querySelectorAll) mountPanelPopups();
  if (panel) mounted?.register(panel);
  return mounted?.open(name, trigger) ?? false;
}

export function mountPanelPopups(root = document) {
  if (mounted) return mounted;
  const panels = new Map();
  let active = null;
  let opener = null;
  const triggers = name => [...root.querySelectorAll(`[data-panel-open="${name}"]`)];
  const visible = node => !node.hidden && node.getClientRects().length > 0;
  const nestedModal = () => [...root.querySelectorAll('[aria-modal="true"], dialog[open], reveal-overlay [data-bind="rvl-backdrop"]')]
    .some(node => node !== active && !node.contains(active) && visible(node));
  const syncContents = panel => {
    const open = panel === active;
    // Only the outer disclosure belongs to this popup. Inner dialogs retain
    // their own state and closing behavior.
    const details = panel.querySelector('details');
    if (details && details.open !== open) details.open = open;
  };
  const close = (name, { restoreFocus = true } = {}) => {
    if (!active || (name && active.dataset.panelPopup !== name)) return false;
    const panel = active;
    active = null;
    panel.hidden = true;
    syncContents(panel);
    for (const button of triggers(panel.dataset.panelPopup)) button.setAttribute('aria-expanded', 'false');
    unlock();
    panel.dispatchEvent(new CustomEvent('app:panel-close', { bubbles: true }));
    if (restoreFocus && opener?.isConnected) opener.focus({ preventScroll: true });
    opener = null;
    return true;
  };
  const open = (name, trigger = triggers(name)[0]) => {
    const panel = panels.get(name);
    if (!panel) return false;
    if (active === panel) return true;
    close(null, { restoreFocus: false });
    active = panel;
    opener = trigger || root.activeElement;
    panel.hidden = false;
    for (const button of triggers(name)) button.setAttribute('aria-expanded', 'true');
    // The backdrop and focus trap own the background. Other app sections can
    // still host shared wallet/reveal/referral dialogs above this popup.
    lock();
    syncContents(panel);
    panel.dispatchEvent(new CustomEvent('app:panel-open', { bubbles: true, detail: { name } }));
    panel.querySelector('[data-panel-close]')?.focus({ preventScroll: true });
    return true;
  };

  const register = panel => {
    const name = panel.dataset.panelPopup;
    if (panels.get(name) === panel) return;
    panels.set(name, panel);
    panel.querySelector('[data-panel-close]')?.addEventListener('click', () => close(name));
    // A drag ending on the backdrop must not dismiss a selection in the panel.
    let backdropStart = false;
    panel.addEventListener('pointerdown', event => { backdropStart = event.target === panel; });
    panel.addEventListener('click', event => {
      if (backdropStart && event.target === panel) close(name);
      backdropStart = false;
    });
    const details = panel.querySelector('details');
    details?.addEventListener('toggle', () => {
      // Existing funding/pass shortcuts open their disclosure programmatically.
      if (details.open && panel.hidden) open(name);
    });
  };
  for (const panel of root.querySelectorAll('[data-panel-popup]')) register(panel);
  root.addEventListener('click', event => {
    const trigger = event.target?.closest?.('[data-panel-open]');
    if (trigger && !trigger.disabled) open(trigger.dataset.panelOpen, trigger);
  });
  root.addEventListener('keydown', event => {
    // An inner dialog may already have handled Escape and hidden itself in
    // a capture listener. Its original event path still owns this keystroke.
    const fromNestedModal = event.composedPath().some(node => node !== active
      && node.matches?.('[role="dialog"], dialog, [data-bind="rvl-backdrop"]')
      && !node.contains(active));
    if (!active || fromNestedModal || nestedModal()) return;
    if (event.key === 'Escape') {
      event.preventDefault();
      close();
    } else if (event.key === 'Tab') {
      const controls = [...active.querySelectorAll('button, a[href], input, select, textarea, [tabindex]')]
        .filter(node => !node.disabled && node.tabIndex >= 0 && visible(node));
      const first = controls[0];
      const last = controls.at(-1);
      if (event.shiftKey && (root.activeElement === first || !active.contains(root.activeElement))) {
        event.preventDefault(); last?.focus();
      } else if (!event.shiftKey && (root.activeElement === last || !active.contains(root.activeElement))) {
        event.preventDefault(); first?.focus();
      }
    }
  });
  mounted = { open, close, register };
  return mounted;
}
